export async function seedCasinoGames(ds: DataSource) {
  const repo = ds.getRepository(GameList);

  await repo
    .createQueryBuilder()
    .delete()
    .where('id >= :id', { id: 5001 })
    .execute();

  for (const g of CASINO_GAMES) {
    const { configJson, rulesJson, ...rest } = g;
    const row = {
      ...rest,
      ...gameColumnsFromConfig(configJson, true),
      isThirdParty: 1,
      status: 1,
    };
    const saved = await repo.save(repo.create(row));
    await insertGameChildConfig(
      ds,
      saved.id,
      g.gameType as string,
      configJson,
      rulesJson,
    );
  }

  console.log('[CasinoGames] Created:', CASINO_GAMES.length, 'games');
}
